package server

import (
	"net/http"
	"time"
	"unicode/utf8"

	"github.com/extube/bleak-node/internal/db"
	"github.com/extube/bleak-node/internal/model"
)

// CreateRoomRequest is the body for POST /api/room.
// The room address is generated by the server and must not be provided.
// The room language (en, default, or ru) is the single language of
// everything inside it: users' greetings, their chats and every message.
// The room token is generated by the client (§7.1): the server stores only
// its SHA-256 hash and never returns the raw secret.
type CreateRoomRequest struct {
	Name        string `json:"name"`
	Description string `json:"description"`
	Language    string `json:"language"`
	Token       string `json:"token"`
}

// UpdateRoomRequest is the body for PUT /api/room/{address}.
type UpdateRoomRequest struct {
	Name        *string `json:"name"`
	Description *string `json:"description"`
}

// CreateRoomResponse is the body returned by POST /api/room: the room plus
// the first invite code minted for it (CONCEPT.md §7.4). The room token is
// NOT returned — the client generated the raw secret itself.
type CreateRoomResponse struct {
	model.Room
	InviteCode string `json:"invite_code" example:"482913"`
}

const (
	maxRoomNameLen = 32
	maxRoomDescLen = 120
)

// CreateRoom creates a new room. Requires a one-time creation token in the
// x-create-token header (consumed on use) and the client-generated room
// token in the body.
//
//	@Summary		create room
//	@Description	Creates a room with a server-generated unique address. Requires a one-time creation token in the x-create-token header (consumed on use) and the client-generated room token in the body (only its SHA-256 hash is stored). The first invite code (24 h expiry) is minted at creation and returned.
//	@Tags			rooms
//	@Accept			json
//	@Produce		json
//	@Param			x-create-token	header	string				true	"One-time room-creation token"
//	@Param			request			body	CreateRoomRequest	true	"Room to create (with the client-generated room token)"
//	@Success		201	{object}	CreateRoomResponse
//	@Failure		400	{object}	string
//	@Failure		401	{object}	string
//	@Failure		403	{object}	string
//	@Failure		409	{object}	string
//	@Router			/api/room [post]
func (s *Server) CreateRoom(w http.ResponseWriter, r *http.Request) {
	var req CreateRoomRequest
	if err := decodeJSON(r, &req); err != nil {
		respond(w, http.StatusBadRequest, message(err))
		return
	}

	if n := utf8.RuneCountInString(req.Name); req.Name == "" || n > maxRoomNameLen {
		respond(w, http.StatusBadRequest, "name is required and must be at most 32 symbols")
		return
	}
	if n := utf8.RuneCountInString(req.Description); n > maxRoomDescLen {
		respond(w, http.StatusBadRequest, "description must be at most 120 symbols")
		return
	}
	language := req.Language
	if language == "" {
		language = model.DefaultLanguage
	}
	if !model.SupportedLanguage(language) {
		respond(w, http.StatusBadRequest, "language must be one of {en, ru}")
		return
	}
	if !validateToken(req.Token) {
		respond(w, http.StatusBadRequest,
			"token is required: a client-generated secret of at least 32 symbols")
		return
	}

	// The one-time creation token is validated and consumed before the
	// insert; a malformed body above does not burn the token, anything
	// after this point does.
	if !s.authCreateToken(w, r) {
		return
	}

	room := model.Room{Name: req.Name, Description: req.Description, Language: language}
	if err := s.db.CreateRoom(r.Context(), &room, db.HashToken(req.Token)); err != nil {
		s.mapError(w, err)
		return
	}
	// The first invite code is minted at room creation and returned to the
	// creator (CONCEPT.md §7.4).
	inv, err := s.db.CreateRoomInvite(r.Context(), room.Address,
		time.Now().UTC().Add(db.DefaultInviteExpiry))
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, CreateRoomResponse{Room: room, InviteCode: inv.Code})
}

// ListRooms lists all rooms.
//
//	@Summary		list rooms
//	@Description	Returns all non-deleted rooms.
//	@Tags			rooms
//	@Produce		json
//	@Success		200	{array}	model.Room
//	@Router			/api/room [get]
func (s *Server) ListRooms(w http.ResponseWriter, r *http.Request) {
	rooms, err := s.db.ListRooms(r.Context())
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, rooms)
}

// GetRoom returns one room.
//
//	@Summary		get room
//	@Description	Returns a non-deleted room by its address.
//	@Tags			rooms
//	@Produce		json
//	@Param			address	path	string	true	"Room address"
//	@Success		200	{object}	model.Room
//	@Failure		404	{object}	string
//	@Router			/api/room/{address} [get]
func (s *Server) GetRoom(w http.ResponseWriter, r *http.Request) {
	room, err := s.db.GetRoom(r.Context(), r.PathValue("address"))
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, room)
}

// UpdateRoom partially updates a room.
//
//	@Summary		update room
//	@Description	Updates name and/or description of a room. Omitted fields keep their value.
//	@Tags			rooms
//	@Accept			json
//	@Produce		json
//	@Param			address			path	string				true	"Room address"
//	@Param			request			body	UpdateRoomRequest	true	"Fields to update"
//	@Success		200	{object}	model.Room
//	@Failure		400	{object}	string
//	@Failure		401	{object}	string
//	@Failure		403	{object}	string
//	@Failure		404	{object}	string
//	@Router			/api/room/{address} [put]
func (s *Server) UpdateRoom(w http.ResponseWriter, r *http.Request) {
	if !s.authRoomToken(w, r, r.PathValue("address")) {
		return
	}
	var req UpdateRoomRequest
	if err := decodeJSON(r, &req); err != nil {
		respond(w, http.StatusBadRequest, message(err))
		return
	}
	if req.Name != nil {
		if n := utf8.RuneCountInString(*req.Name); *req.Name == "" || n > maxRoomNameLen {
			respond(w, http.StatusBadRequest, "name must be non-empty and at most 32 symbols")
			return
		}
	}
	if req.Description != nil && utf8.RuneCountInString(*req.Description) > maxRoomDescLen {
		respond(w, http.StatusBadRequest, "description must be at most 120 symbols")
		return
	}

	room, err := s.db.UpdateRoom(r.Context(), r.PathValue("address"), req.Name, req.Description)
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, room)
}

// DeleteRoom soft-deletes a room.
//
//	@Summary		delete room
//	@Description	Soft-deletes a room together with its linked users.
//	@Tags			rooms
//	@Security		RoomToken
//	@Param			address	path	string	true	"Room address"
//	@Success		200	{object}	model.Room
//	@Failure		401	{object}	string
//	@Failure		403	{object}	string
//	@Failure		404	{object}	string
//	@Router			/api/room/{address} [delete]
func (s *Server) DeleteRoom(w http.ResponseWriter, r *http.Request) {
	if !s.authRoomToken(w, r, r.PathValue("address")) {
		return
	}
	room, err := s.db.DeleteRoom(r.Context(), r.PathValue("address"))
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, room)
}
